pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, uint64 ts) public {
        amount = bound(amount, 0, type(uint128).max);
        ts = uint64(bound(ts, 1, type(uint64).max / 2));

        vm.deal(address(this), amount);
        vm.roll(1); // block.number % 15 != 0 -> no payout path
        vm.warp(ts); // block.timestamp > pastBlockTime (initially 0)

        uint256 balBefore = address(c).balance;
        bool ok;
        if (amount > 0) {
            vm.prank(address(this));
            try c.fallback{value: amount}() {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            vm.prank(address(this));
            try c.fallback{value: 0}() {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // General rule: whenever a call is accepted, the contract's balance
        // grows by exactly 10 ether; calls with any other value must revert.
        assertTrue(!ok || address(c).balance == balBefore + 10 ether);
    }
}

