pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 t1, uint64 t2) public {
        vm.assume(t1 > 0);
        t2 = bound(t2, 0, t1 - 1); // t2 strictly earlier than t1

        // First call at time t1: always accepted by both versions.
        vm.warp(t1);
        vm.roll(block.number);
        address actor = address(0xA11ce);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        uint256 pastAfterFirst = c.pastBlockTime();
        assertEq(pastAfterFirst, t1);

        // Second call at an EARLIER timestamp t2:
        // invariant: pastBlockTime must never decrease across accepted calls.
        vm.warp(t2);
        vm.roll(block.number + 1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        assertTrue(!ok2 || c.pastBlockTime() > pastAfterFirst);
    }
}

