pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 blockNumber, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        blockNumber = bound(blockNumber, 15, type(uint256).max - 1);
        // choose a block number divisible by 15 so the payout condition holds
        blockNumber = blockNumber - (blockNumber % 15);
        vm.roll(blockNumber);
        vm.warp(block.timestamp + 1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        // Rule: after a successful 10-ether call in a block divisible by 15,
        // the contract pays out everything, so its balance must be zero.
        assertTrue(address(c).balance == 0, "contract must pay out its balance when block.number % 15 == 0");
    }
}

